// ============================================================
//  MURBAN CRUDE OIL — FUTURES TELEGRAM ALERT
//  n8n Code Node | Mode: Run Once for All Items
// ============================================================

// --- CONTRACT DATA (from OilPrice.com scrape / upstream node) ---
// Replace this array with $input.all() if fetching live via HTTP Request node
const contracts = [
  { name: "Jul 2026", symbol: "DBN26", last: 92.82, change: -9.39, open: 96.04, high: 96.04, low: 92.82 },
  { name: "Aug 2026", symbol: "DBQ26", last: 89.50, change: -1.10, open: 90.60, high: 90.60, low: 89.50 },
  { name: "Dec 2026", symbol: "DBZ26", last: 84.20, change: -0.95, open: 85.15, high: 85.15, low: 84.20 },
  { name: "Jan 2027", symbol: "DBF27", last: 82.50, change: -0.88, open: 83.38, high: 83.38, low: 82.50 },
  { name: "Jul 2027", symbol: "DBN27", last: 79.80, change: -0.75, open: 80.55, high: 80.55, low: 79.80 },
  { name: "Jan 2028", symbol: "DBF28", last: 77.40, change: -0.65, open: 78.05, high: 78.05, low: 77.40 },
  { name: "Jul 2028", symbol: "DBN28", last: 76.20, change: -0.60, open: 76.80, high: 76.80, low: 76.20 },
  { name: "Jan 2029", symbol: "DBF29", last: 74.71, change: -1.21, open: 74.71, high: 74.71, low: 74.71 },
  { name: "Jul 2029", symbol: "DBN29", last: 74.20, change: -0.97, open: 74.20, high: 74.20, low: 74.20 },
  { name: "Jan 2030", symbol: "DBF30", last: 73.73, change: -0.68, open: 73.73, high: 73.73, low: 73.73 },
  { name: "May 2030", symbol: "DBK30", last: 73.57, change: -0.48, open: 73.57, high: 73.57, low: 73.57 },
];

// ---- HELPER FUNCTIONS ----
function arrow(change) {
  return change > 0 ? "🟢 ▲" : change < 0 ? "🔴 ▼" : "⚪ —";
}

function fmt(num) {
  return Number(num).toFixed(2);
}

function sign(num) {
  return num > 0 ? `+${fmt(num)}` : `${fmt(num)}`;
}

function trendEmoji(change) {
  if (change > 1) return "🚀";
  if (change > 0) return "📈";
  if (change < -3) return "🆘";
  if (change < 0) return "📉";
  return "➡️";
}

// ---- DATE & TIME ----
const now = new Date();
const dateStr = now.toLocaleDateString("en-IN", {
  weekday: "long", year: "numeric", month: "long", day: "numeric",
  timeZone: "Asia/Dubai"
});
const timeStr = now.toLocaleTimeString("en-IN", {
  hour: "2-digit", minute: "2-digit", timeZone: "Asia/Dubai", timeZoneName: "short"
});

// ---- FRONT MONTH (first contract = spot/near) ----
const front = contracts[0];
const frontDir = front.change >= 0 ? "UP" : "DOWN";
const mktSentiment = front.change > 1 ? "BULLISH 🐂" 
                   : front.change > 0 ? "MILDLY BULLISH 📊"
                   : front.change < -3 ? "BEARISH 🐻"
                   : front.change < 0 ? "MILDLY BEARISH 📊"
                   : "NEUTRAL ➡️";

// ---- BUILD CONTRACT TABLE ROWS (near-term 6 contracts) ----
const nearTerm = contracts.slice(0, 6);
const contractRows = nearTerm.map(c => {
  const dir = arrow(c.change);
  return `  <code>${c.name.padEnd(9)}</code>  <b>$${fmt(c.last)}</b>  ${dir} <i>${sign(c.change)}</i>`;
}).join("\n");

// ---- CURVE SUMMARY (full forward curve) ----
const curveRows = contracts.map(c => {
  const bar = c.change >= 0 ? "▲" : "▼";
  return `<code>${c.symbol}</code> | ${c.name} | <b>$${fmt(c.last)}</b> ${bar}`;
}).join("\n");

// ---- SPREAD: Front vs Back ----
const spread = contracts[0].last - contracts[contracts.length - 1].last;
const curveShape = spread > 2 ? "🔴 <b>Backwardation</b> (spot premium)" 
                 : spread < -2 ? "🟢 <b>Contango</b> (deferred premium)"
                 : "⚪ <b>Flat Curve</b>";

// ---- ASSEMBLE TELEGRAM MESSAGE ----
const message = `
🛢️ <b>MURBAN CRUDE OIL — FUTURES REPORT</b>
<i>ICE Futures Abu Dhabi (IFAD) | FOB Fujairah</i>
━━━━━━━━━━━━━━━━━━━━
📅 <b>${dateStr}</b>
🕐 <b>${timeStr}</b>

━━━━━━━━━━━━━━━━━━━━
🔆 <b>FRONT MONTH: ${front.name}</b>
💵 <b>Price:</b> <code>$${fmt(front.last)} / bbl</code>
${trendEmoji(front.change)} <b>Change:</b> <code>${sign(front.change)} (${sign((front.change/front.open*100).toFixed(2))}%)</code>
📂 <b>Open:</b> $${fmt(front.open)}   📊 <b>Range:</b> $${fmt(front.low)} – $${fmt(front.high)}
🌡️ <b>Market Sentiment:</b> ${mktSentiment}

━━━━━━━━━━━━━━━━━━━━
📋 <b>NEAR-TERM FUTURES (6 Contracts)</b>

${contractRows}

━━━━━━━━━━━━━━━━━━━━
📐 <b>FORWARD CURVE SHAPE</b>
${curveShape}
↔️ <b>Spread (Front vs Dec'30):</b> <code>${sign(spread.toFixed(2))} $/bbl</code>

━━━━━━━━━━━━━━━━━━━━
📊 <b>FULL FORWARD CURVE</b>

${curveRows}

━━━━━━━━━━━━━━━━━━━━
ℹ️ <i>Murban: UAE Light Crude | API ~39.9° | Sulfur ~0.79%</i>
🏭 <i>Produced by ADNOC | Delivered FOB Fujairah, UAE</i>
🔗 <i>Source: OilPrice.com / ICE IFAD</i>
━━━━━━━━━━━━━━━━━━━━
`.trim();

// ---- OUTPUT FOR TELEGRAM NODE ----
return [{
  json: {
    chat_id: "YOUR_CHAT_ID",          // 🔁 Replace with your Telegram chat/channel ID
    text: message,
    parse_mode: "HTML",
    disable_web_page_preview: true,
  }
}];
